import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.1
.target sm_89
.address_size 64

.visible .entry tanh_forward(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 n_elts
)
{
    .reg .pred  %p;
    .reg .u32   %r_tid, %r_bdim, %r_bidx, %r_gdim, %r_idx, %r_n, %r_stride;
    .reg .u64   %in, %out, %in_g, %out_g, %addr_in, %addr_out, %offset;
    .reg .f32   %x, %two, %neg, %log2e, %y, %t, %one, %num, %den, %res;

    // Load parameters
    ld.param.u64 %in,  [in_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.u32 %r_n, [n_elts];

    // Convert to global space
    cvta.to.global.u64 %in_g,  %in;
    cvta.to.global.u64 %out_g, %out;

    // Thread/block/grid indices
    mov.u32 %r_tid,  %tid.x;
    mov.u32 %r_bdim, %ntid.x;
    mov.u32 %r_bidx, %ctaid.x;
    mov.u32 %r_gdim, %nctaid.x;

    mul.lo.u32 %r_idx, %r_bdim, %r_bidx;
    add.u32    %r_idx, %r_idx, %r_tid;
    mul.lo.u32 %r_stride, %r_bdim, %r_gdim;

    setp.ge.u32 %p, %r_idx, %r_n;
    @%p bra DONE;

    mov.f32 %one,   1.0;
    mov.f32 %log2e, 1.44269502;

LOOP:
    mul.wide.u32 %offset, %r_idx, 4;
    add.u64 %addr_in,  %in_g,  %offset;
    add.u64 %addr_out, %out_g, %offset;

    ld.global.f32 %x, [%addr_in];

    // tanh(x) = (1 - exp(-2x)) / (1 + exp(-2x))
    add.f32 %two, %x, %x;        // two = 2*x
    neg.f32 %neg, %two;          // neg = -2*x
    mul.f32 %y, %neg, %log2e;    // y = -2*x * log2(e)
    ex2.approx.f32 %t, %y;       // t = 2^y = exp(-2*x)
    sub.f32 %num, %one, %t;      // num = 1 - t
    add.f32 %den, %one, %t;      // den = 1 + t
    div.rn.f32 %res, %num, %den; // res = num / den

    st.global.f32 [%addr_out], %res;

    add.u32 %r_idx, %r_idx, %r_stride;
    setp.lt.u32 %p, %r_idx, %r_n;
    @%p bra LOOP;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("tanh_forward")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensor input.")
        if x.dtype != torch.float32:
            raise RuntimeError("ModelNew only supports torch.float32 dtype.")
        if not x.is_contiguous():
            x = x.contiguous()

        numel = x.numel()
        y = torch.empty(x.shape, dtype=x.dtype, device=x.device)

        block_x = 256
        grid_x = min((numel + block_x - 1) // block_x, 65535)

        module = _get_ptx_module()
        module.launch(
            "tanh_forward",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, y, i32(numel)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

